static const Id128 MVS_MISSION=id_from_seed("GENESIS-MVS-001-CANARY");static const Id128 MVS_TASK=id_from_seed("GENESIS-MVS-001-WRITE");static const Id128 MVS_CORR=id_from_seed("GENESIS-MVS-001-CORR");static constexpr char OLD_TEXT[]="FUSE-GENESIS-OLD-V1";static constexpr char NEW_TEXT[]="FUSE-GENESIS-NEW-V1";
static Status event_payload(EventType e,const Digest256*task,const Digest256*nonce,const Id128*permit,Buffer*out){FcbWriter w{};auto st=fcb_begin(&w,(u16)(0x4000+(u32)e),0);if(st!=Status::Ok)return st;if(task)fcb_put_bytes(&w,1,FcbType::DIGEST256,{task->bytes.data(),32});if(nonce)fcb_put_bytes(&w,2,FcbType::DIGEST256,{nonce->bytes.data(),32});if(permit)fcb_put_bytes(&w,3,FcbType::BYTES,{permit->bytes.data(),16});return fcb_finish(&w,out,nullptr);}
Status runtime_open(const std::wstring&root,Runtime*out){if(!out)return Status::InvalidArgument;*out=Runtime{};out->root=root;out->state_root=(std::filesystem::path(root)/L"state").wstring();out->workspace_root=(std::filesystem::path(root)/L"workspace").wstring();auto objects=(std::filesystem::path(root)/L"objects").wstring();ensure_directory(out->state_root);ensure_directory(out->workspace_root);ensure_directory(objects);auto st=journal_writer_open(out->state_root,&out->journal);if(st!=Status::Ok)return st;if((st=object_store_open(objects,&out->objects))!=Status::Ok)return st;if((st=registry_initialize(&out->registry))!=Status::Ok)return st;if((st=register_root(1,out->workspace_root,true,true,&out->workspace))!=Status::Ok)return st;return identity_open_or_create(&out->identity,L"FUSE-GENESIS-MVS-P256-V1");}
void runtime_close(Runtime*r){if(r)identity_close(&r->identity);}Status task_digest(const TaskEnvelope*t,Digest256*out){if(!t||!out)return Status::InvalidArgument;FcbWriter w{};fcb_begin(&w,0x4101,0);fcb_put_bytes(&w,1,FcbType::BYTES,{t->mission_id.bytes.data(),16});fcb_put_u64(&w,2,t->mission_version);fcb_put_bytes(&w,3,FcbType::BYTES,{t->task_id.bytes.data(),16});fcb_put_u64(&w,4,t->capability_id);fcb_put_bytes(&w,5,FcbType::DIGEST256,{t->registry_root.bytes.data(),32});fcb_put_bytes(&w,6,FcbType::DIGEST256,{t->canonical_arguments_hash.bytes.data(),32});fcb_put_bytes(&w,7,FcbType::DIGEST256,{t->nonce.bytes.data(),32});fcb_put_bytes(&w,8,FcbType::DIGEST256,{t->idempotency_key.bytes.data(),32});Buffer b;return fcb_finish(&w,&b,out);}Status append_event(Runtime*r,EventType e,ByteSpan p){return journal_append(&r->journal,&MVS_MISSION,1,(u32)e,p,nullptr);}
static Status projection_cb(const JournalRecordView*v,void*ctx){auto*p=(TaskSecurityProjection*)ctx;ByteSpan task{},nonce{},permit{};fcb_get_bytes(v->payload,1,&task);fcb_get_bytes(v->payload,2,&nonce);fcb_get_bytes(v->payload,3,&permit);if(task.size==32)bytes_copy(p->task_digest.bytes.data(),task.data,32);if(nonce.size==32)bytes_copy(p->nonce.bytes.data(),nonce.data,32);if(permit.size==16)bytes_copy(p->permit_id.bytes.data(),permit.data,16);switch((EventType)v->event_type){case EventType::MISSION_CREATED:p->mission_created=true;break;case EventType::TASK_RECEIVED:p->task_received=true;break;case EventType::TASK_VALIDATED:p->task_validated=true;break;case EventType::NONCE_CLAIMED:p->nonce_claimed=true;break;case EventType::IDEMPOTENCY_CLAIMED:p->idempotency_claimed=true;break;case EventType::ACTION_PREPARED:p->action_prepared=true;break;case EventType::PERMIT_ISSUED:p->permit_issued=true;break;case EventType::PERMIT_CONSUMED:p->permit_consumed=true;break;case EventType::EXECUTION_STARTED:p->execution_started=true;break;case EventType::EFFECT_RECONCILING:p->effect_reconciling=true;break;case EventType::EFFECT_OBSERVED:p->effect_observed=true;break;case EventType::RESULT_OBSERVED:p->result_observed=true;break;case EventType::RESULT_ATTESTED:p->result_attested=true;break;case EventType::TASK_PROVEN:p->task_proven=true;break;case EventType::MISSION_COMPLETE_VERIFIED:p->mission_complete=true;break;default:break;}return Status::Ok;}
Status project_runtime(Runtime*r,TaskSecurityProjection*out){if(!r||!out)return Status::InvalidArgument;*out=TaskSecurityProjection{};return journal_replay_all(r->state_root,projection_cb,out);}Status nonce_claim(Runtime*r,const Digest256&task,const Digest256&nonce){TaskSecurityProjection p{};auto st=project_runtime(r,&p);if(st!=Status::Ok)return st;if(p.nonce_claimed&&p.nonce==nonce)return Status::NonceReplay;Buffer ev;event_payload(EventType::NONCE_CLAIMED,&task,&nonce,nullptr,&ev);return append_event(r,EventType::NONCE_CLAIMED,{ev.data(),(u64)ev.size()});}
Status permit_issue(Runtime*r,const PreparedAction*a,ExecutionPermit*out){if(!r||!a||!out)return Status::InvalidArgument;TaskSecurityProjection p{};project_runtime(r,&p);if(p.permit_issued&&!p.task_proven)return Status::NonceReplay;out->permit_id=id_from_seed("GENESIS-MVS-PERMIT");out->task_id=a->task_id;out->effect_id=a->effect_id;out->prepared_digest=a->prepared_digest;Buffer ev;event_payload(EventType::PERMIT_ISSUED,&a->task_digest,nullptr,&out->permit_id,&ev);return append_event(r,EventType::PERMIT_ISSUED,{ev.data(),(u64)ev.size()});}Status permit_consume(Runtime*r,const ExecutionPermit*p){TaskSecurityProjection s{};project_runtime(r,&s);if(s.permit_consumed)return Status::PermitAlreadyConsumed;Buffer ev;event_payload(EventType::PERMIT_CONSUMED,nullptr,nullptr,&p->permit_id,&ev);return append_event(r,EventType::PERMIT_CONSUMED,{ev.data(),(u64)ev.size()});}
static std::wstring marker_path(const std::wstring&root){return (std::filesystem::path(root)/L"workspace"/L"canary"/L"write_count.txt").wstring();}static Status marker_increment(const std::wstring&root){auto p=marker_path(root);ensure_directory(std::filesystem::path(p).parent_path().wstring());Buffer b;u64 n=0;if(file_read_path(p,&b)==Status::Ok&&!b.empty()&&b[0]>='0'&&b[0]<='9')n=b[0]-'0';std::string s=std::to_string(n+1);return file_write_durable(p,{(const u8*)s.data(),(u64)s.size()},false);}static u64 marker_read(const std::wstring&root){Buffer b;if(file_read_path(marker_path(root),&b)!=Status::Ok||b.empty()||b[0]<'0'||b[0]>'9')return 0;return b[0]-'0';}
static TaskEnvelope make_canary_task(const Runtime&r,const ObjectRef&neo){TaskEnvelope t{};t.mission_id=MVS_MISSION;t.task_id=MVS_TASK;t.correlation_id=MVS_CORR;t.capability_id=CAP_FILE_WRITE_ATOMIC;t.registry_root=r.registry.root_hash;t.canonical_arguments_hash=neo.digest;sha256({(const u8*)"GENESIS-MVS-NONCE",17},&t.nonce);sha256({(const u8*)"GENESIS-MVS-IDEMPOTENCY",23},&t.idempotency_key);t.effect_class=(u16)CapabilityEffect::REVERSIBLE;return t;}
int run_mvs_crash_child(const std::wstring&root){Runtime r{};if(runtime_open(root,&r)!=Status::Ok)return 20;ObjectRef neo{};if(object_put(&r.objects,{(const u8*)NEW_TEXT,sizeof(NEW_TEXT)-1},0x5001,&neo)!=Status::Ok){runtime_close(&r);return 21;}TaskEnvelope t=make_canary_task(r,neo);Digest256 td{};task_digest(&t,&td);Digest256 old{};sha256({(const u8*)OLD_TEXT,sizeof(OLD_TEXT)-1},&old);FileWritePrepared prep{};auto st=file_write_prepare(&r.workspace,&r.objects,L"canary\\state.bin",neo,true,&old,true,&prep);if(st!=Status::Ok){runtime_close(&r);return 22;}ExecutionPermit p{};p.permit_id=id_from_seed("GENESIS-MVS-PERMIT");p.task_id=MVS_TASK;p.effect_id=neo.digest;p.prepared_digest=prep.prepared_digest;if(permit_consume(&r,&p)!=Status::Ok){runtime_close(&r);return 23;}Buffer ev;event_payload(EventType::EXECUTION_STARTED,&td,nullptr,&p.permit_id,&ev);append_event(&r,EventType::EXECUTION_STARTED,{ev.data(),(u64)ev.size()});marker_increment(root);FileHashResult res{};st=file_write_execute(&r.objects,&prep,&res);runtime_close(&r);if(st!=Status::Ok)return 24;TerminateProcess(GetCurrentProcess(),0x47A5);return 0;}
int run_mvs_canary(const std::wstring&root){Runtime r{};auto st=runtime_open(root,&r);if(st!=Status::Ok)return 30;ensure_directory((std::filesystem::path(r.workspace_root)/L"canary").wstring());auto target=(std::filesystem::path(r.workspace_root)/L"canary"/L"state.bin").wstring();TaskSecurityProjection p{};project_runtime(&r,&p);ObjectRef neo{};object_put(&r.objects,{(const u8*)NEW_TEXT,sizeof(NEW_TEXT)-1},0x5001,&neo);TaskEnvelope t=make_canary_task(r,neo);Digest256 td{};task_digest(&t,&td);if(p.task_proven&&p.mission_complete){FileHashResult h{};bool ok=file_hash_authorized(&r.workspace,L"canary\\state.bin",&h)==Status::Ok&&h.digest==neo.digest&&marker_read(root)==1;runtime_close(&r);return ok?0:31;}if(!p.mission_created){file_write_durable(target,{(const u8*)OLD_TEXT,sizeof(OLD_TEXT)-1},false);Buffer ev;event_payload(EventType::MISSION_CREATED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::MISSION_CREATED,{ev.data(),(u64)ev.size()});event_payload(EventType::TASK_RECEIVED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::TASK_RECEIVED,{ev.data(),(u64)ev.size()});event_payload(EventType::TASK_VALIDATED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::TASK_VALIDATED,{ev.data(),(u64)ev.size()});if(nonce_claim(&r,td,t.nonce)!=Status::Ok){runtime_close(&r);return 32;}event_payload(EventType::IDEMPOTENCY_CLAIMED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::IDEMPOTENCY_CLAIMED,{ev.data(),(u64)ev.size()});event_payload(EventType::ACTION_PREPARED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::ACTION_PREPARED,{ev.data(),(u64)ev.size()});PreparedAction a{};a.task_id=MVS_TASK;a.task_digest=td;a.effect_id=neo.digest;a.prepared_digest=neo.digest;ExecutionPermit permit{};if(permit_issue(&r,&a,&permit)!=Status::Ok){runtime_close(&r);return 33;}runtime_close(&r);DWORD ec=0;if(launch_court_child(self_path(),"MVS-CRASH",root,&ec)!=Status::Ok||ec!=0x47A5)return 34;if(runtime_open(root,&r)!=Status::Ok)return 35;project_runtime(&r,&p);}if(p.permit_consumed&&p.execution_started&&!p.effect_observed){Buffer ev;event_payload(EventType::EFFECT_RECONCILING,&td,nullptr,nullptr,&ev);append_event(&r,EventType::EFFECT_RECONCILING,{ev.data(),(u64)ev.size()});FileHashResult h{};if(file_hash_authorized(&r.workspace,L"canary\\state.bin",&h)!=Status::Ok||h.digest!=neo.digest){runtime_close(&r);return 36;}event_payload(EventType::EFFECT_OBSERVED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::EFFECT_OBSERVED,{ev.data(),(u64)ev.size()});event_payload(EventType::RESULT_OBSERVED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::RESULT_OBSERVED,{ev.data(),(u64)ev.size()});FcbWriter bodyW{};fcb_begin(&bodyW,0x4201,0);fcb_put_bytes(&bodyW,1,FcbType::DIGEST256,{td.bytes.data(),32});fcb_put_bytes(&bodyW,2,FcbType::DIGEST256,{h.digest.bytes.data(),32});Buffer body;Digest256 bodyHash{};fcb_finish(&bodyW,&body,&bodyHash);Buffer sig;if(identity_sign(&r.identity,&bodyHash,&sig)!=Status::Ok||identity_verify(&r.identity,&bodyHash,{sig.data(),(u64)sig.size()})!=Status::Ok){runtime_close(&r);return 37;}FcbWriter attW{};fcb_begin(&attW,0x4202,0);fcb_put_bytes(&attW,1,FcbType::DIGEST256,{td.bytes.data(),32});fcb_put_bytes(&attW,2,FcbType::DIGEST256,{h.digest.bytes.data(),32});fcb_put_bytes(&attW,3,FcbType::BYTES,{sig.data(),(u64)sig.size()});fcb_put_u64(&attW,4,r.identity.software_fallback?1:0);Buffer attBytes;Digest256 attHash{};fcb_finish(&attW,&attBytes,&attHash);ObjectRef attObj{};if(object_put(&r.objects,{attBytes.data(),(u64)attBytes.size()},0x5002,&attObj)!=Status::Ok){runtime_close(&r);return 38;}event_payload(EventType::RESULT_ATTESTED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::RESULT_ATTESTED,{ev.data(),(u64)ev.size()});event_payload(EventType::TASK_PROVEN,&td,nullptr,nullptr,&ev);append_event(&r,EventType::TASK_PROVEN,{ev.data(),(u64)ev.size()});event_payload(EventType::MISSION_COMPLETE_VERIFIED,&td,nullptr,nullptr,&ev);append_event(&r,EventType::MISSION_COMPLETE_VERIFIED,{ev.data(),(u64)ev.size()});}project_runtime(&r,&p);FileHashResult final{};bool ok=p.task_proven&&p.mission_complete&&file_hash_authorized(&r.workspace,L"canary\\state.bin",&final)==Status::Ok&&final.digest==neo.digest&&marker_read(root)==1;runtime_close(&r);return ok?0:39;}
